"""Purple-pirate theme for the scheduling app.

Night-sky purple fading to a misty pink horizon, gold trim, floating embers,
a pirate ship sailing across the header, and a little wise owl who pops up
while the timetable is being generated.

Usage in app.py, right after st.set_page_config(...):
    from theme import inject_theme, hero, mascot, gen_overlay, treasure_pop
    inject_theme()
    hero()                       # animated header strip
    mascot()                     # (inside st.sidebar) school picture

    stage = st.empty()
    stage.markdown(gen_overlay(), unsafe_allow_html=True)   # while working
    stage.empty()
    st.markdown(treasure_pop(clean=True), unsafe_allow_html=True)  # on success

Also drop .streamlit/config.toml next to app.py so Streamlit's own widgets
(tables, pickers) use the same dark palette.
"""
import random
import streamlit as st

# palette
NIGHT, DEEP, PLUM, VIOLET = "#12062B", "#1D0B40", "#3A1A6E", "#6B34C8"
ORCHID, PINK, BLUSH = "#B15CF0", "#F06BC4", "#F7B5E6"
GOLD, TEAL, EMBER, PARCHMENT = "#F2C14E", "#47D7C8", "#FF9A3C", "#FFF1D6"


def _flat(s):
    """Streamlit's markdown parser ends an HTML block at a blank line and
    treats 4-space indents as code, so we squash markup onto one line."""
    return "".join(line.strip() for line in s.strip().splitlines())


_CSS = """
<style>
@import url('https://fonts.googleapis.com/css2?family=Lilita+One&family=Fredoka:wght@400;500;600&display=swap');

:root {
  --night:#12062B; --deep:#1D0B40; --plum:#3A1A6E; --violet:#6B34C8;
  --orchid:#B15CF0; --pink:#F06BC4; --blush:#F7B5E6;
  --gold:#F2C14E; --gold-d:#B8862B; --teal:#47D7C8; --ember:#FF9A3C;
  --parch:#FFF1D6; --text:#F6EBFF;
  --glow:0 0 28px rgba(240,107,196,.45);
}

/* ---------- page: night sky melting into a pink horizon ---------- */
html, body, .stApp, .stApp p, .stApp label, input, textarea, button,
[data-baseweb="tab"], li { font-family:'Fredoka', sans-serif; }
[data-testid="stIconMaterial"] { font-family:'Material Symbols Rounded' !important; }
.stApp {
  color:var(--text);
  background:
    radial-gradient(ellipse at 50% 112%, rgba(240,107,196,.6), transparent 58%),
    radial-gradient(ellipse at 12% -4%, rgba(107,52,200,.6), transparent 52%),
    linear-gradient(180deg, #12062B 0%, #2A1060 55%, #5B2A9E 100%) fixed;
}
header[data-testid="stHeader"] { background:transparent; }

[data-testid="stMainBlockContainer"], .block-container {
  background:linear-gradient(180deg, rgba(29,11,64,.84), rgba(18,6,43,.9));
  border:2px solid rgba(242,193,78,.6); border-radius:26px;
  box-shadow:0 0 0 6px rgba(107,52,200,.28), 0 24px 80px rgba(240,107,196,.26),
             inset 0 0 70px rgba(177,92,240,.12);
  max-width:min(1400px, calc(100% - 3rem)) !important;
  margin:1rem auto 2.5rem !important;
  padding:2.2rem 2.4rem 3rem !important;
}

/* ---------- drifting mist + rising embers (fixed, behind and over the panel) ---------- */
.mist-a, .mist-b { position:fixed; left:-25%; width:150%; bottom:-8vh; height:48vh;
  pointer-events:none; z-index:0; filter:blur(34px); opacity:.55;
  background:radial-gradient(ellipse at 30% 60%, rgba(247,181,230,.55), transparent 60%),
             radial-gradient(ellipse at 75% 70%, rgba(177,92,240,.5), transparent 58%);
  animation:mist 26s ease-in-out infinite alternate; }
.mist-b { bottom:-14vh; opacity:.4; animation-duration:38s; animation-direction:alternate-reverse; }
.embers { position:fixed; inset:0; pointer-events:none; z-index:2; overflow:hidden; }
.embers i { position:absolute; bottom:-14px; width:var(--s); height:var(--s); border-radius:50%;
  background:var(--ember); box-shadow:0 0 8px 2px rgba(255,154,60,.7); opacity:0;
  animation:ember var(--d) linear var(--delay) infinite; }
.embers i:nth-child(3n) { background:var(--pink); box-shadow:0 0 9px 2px rgba(240,107,196,.8); }
.embers i:nth-child(5n) { background:var(--gold); box-shadow:0 0 8px 2px rgba(242,193,78,.7); }
@keyframes ember { 0% { transform:translate(0,0); opacity:0; } 10% { opacity:.95; }
  70% { opacity:.7; } 100% { transform:translate(var(--sway),-108vh); opacity:0; } }
@keyframes mist { from { transform:translateX(-6%); } to { transform:translateX(6%); } }

/* ---------- type ---------- */
h1 {
  font-family:'Lilita One', sans-serif !important; font-weight:400 !important;
  text-transform:uppercase; letter-spacing:.04em; line-height:1.05;
  font-size:clamp(2rem, 5vw, 3.5rem) !important; padding:.2em 0 .1em !important;
  text-shadow:0 3px 0 var(--violet), 0 6px 0 #2A1060, 0 0 30px rgba(240,107,196,.8);
  animation:title-glow 4s ease-in-out infinite;
}
h1, h1 * { color:#fff !important; }
@keyframes title-glow { 50% { text-shadow:0 3px 0 var(--violet), 0 6px 0 #2A1060, 0 0 48px rgba(247,181,230,1); } }
h2, h3 { font-family:'Lilita One', sans-serif !important; font-weight:400 !important;
  letter-spacing:.02em; text-shadow:0 2px 0 rgba(0,0,0,.35); }
h2, h3, h2 *, h3 * { color:var(--gold) !important; }
h2::before, h3::before { content:"\\2726"; color:var(--pink); margin-right:.45em; display:inline-block;
  animation:twinkle 2.4s ease-in-out infinite; }
[data-testid="stCaptionContainer"], [data-testid="stCaptionContainer"] *, .stApp small {
  color:var(--blush) !important; opacity:1 !important; }
[data-testid="stCaptionContainer"] { margin:.5rem 0 .3rem; font-size:1rem; }
[data-testid="stWidgetLabel"] *, .stApp label { color:var(--parch) !important; font-weight:500; }
.stApp strong { color:var(--gold); }

hr { border:0 !important; height:0; margin:1.6rem 0 !important; opacity:1 !important;
     border-top:3px dotted rgba(242,193,78,.55) !important; }

/* ---------- hero: ship at night ---------- */
.hero { position:relative; height:200px; margin:.4rem 0 1.8rem; overflow:hidden;
  border:2px solid var(--gold); border-radius:22px;
  background:radial-gradient(ellipse at 72% 100%, rgba(247,181,230,.85), transparent 60%),
             linear-gradient(180deg, #1D0B40 0%, #4A1F8F 55%, #B157C9 100%);
  box-shadow:0 0 0 5px rgba(107,52,200,.35), var(--glow); }
.hero .stars { position:absolute; inset:0 0 40% 0; animation:twinkle 3s ease-in-out infinite;
  background:
   radial-gradient(1.6px 1.6px at 8% 22%, #fff, transparent), radial-gradient(1.2px 1.2px at 22% 48%, #fff, transparent),
   radial-gradient(2px 2px at 36% 16%, #fff, transparent),   radial-gradient(1.2px 1.2px at 52% 38%, #fff, transparent),
   radial-gradient(1.6px 1.6px at 64% 12%, #fff, transparent), radial-gradient(1.2px 1.2px at 78% 30%, #fff, transparent),
   radial-gradient(2px 2px at 90% 14%, #fff, transparent); }
.hero .moon { position:absolute; right:30%; top:18px; width:52px; height:52px; border-radius:50%;
  background:radial-gradient(circle at 35% 35%, #FFF8E6, #F7D9A0 70%);
  box-shadow:0 0 30px 8px rgba(247,181,230,.55); animation:bob 5s ease-in-out infinite; }
.hero .tag { position:absolute; left:24px; top:18px; z-index:5; font-family:'Lilita One', sans-serif;
  font-size:clamp(1.3rem, 3.2vw, 2.3rem); line-height:1; color:#fff; text-transform:uppercase;
  text-shadow:0 3px 0 var(--violet), 0 5px 0 #1D0B40, 0 0 18px rgba(240,107,196,.9); }
.hero .tag small { display:block; margin-top:.6rem; font-family:'Fredoka', sans-serif; font-size:.85rem;
  letter-spacing:.14em; color:var(--gold); text-shadow:0 1px 0 #1D0B40; text-transform:none; }
.hero .fog { position:absolute; left:-10%; width:130%; height:80px; bottom:30px; z-index:3;
  background:radial-gradient(ellipse at center, rgba(247,181,230,.5), transparent 65%);
  animation:fog 14s ease-in-out infinite alternate; }
.hero .sail { position:absolute; left:-170px; bottom:20px; width:150px; z-index:3;
  animation:sail 26s linear infinite; }
.hero .ship { display:block; width:100%; transform-origin:50% 90%;
  animation:rock 5s ease-in-out infinite; filter:drop-shadow(0 0 12px rgba(240,107,196,.6)); }
.hero:hover .ship { animation-duration:2.2s; }
.hero .kraken { position:absolute; left:46%; bottom:34px; width:70px; z-index:3; animation:peek 4.5s ease-in-out infinite; }
.hero .parrot { position:absolute; top:78px; left:-50px; font-size:26px; z-index:3;
  animation:fly 16s linear infinite, flap 1.1s ease-in-out infinite; }
.hero .wave { position:absolute; left:0; right:0; height:46px; --wc:#3A1A6E;
  background:radial-gradient(circle at 20px 22px, var(--wc) 19px, transparent 20px) 0 0/40px 44px repeat-x,
             linear-gradient(var(--wc), var(--wc)) 0 21px/100% 100% no-repeat; }
.hero .w2 { bottom:22px; --wc:#7C3FC8; z-index:2; animation:wave 7s linear infinite; }
.hero .w1 { bottom:-6px; --wc:#2A1060; z-index:4; animation:wave 4.5s linear infinite reverse; }
@keyframes wave { from { background-position:0 0, 0 21px; } to { background-position:40px 0, 0 21px; } }
@keyframes rock { 0%,100% { transform:rotate(-3deg) translateY(0); } 50% { transform:rotate(3deg) translateY(-6px); } }
@keyframes sail { from { left:-170px; } to { left:100%; } }
@keyframes peek { 0%,100% { transform:translateY(30px); } 50% { transform:translateY(0); } }
@keyframes fly  { from { left:-50px; } to { left:calc(100% + 10px); } }
@keyframes flap { 0%,100% { transform:scaleX(-1) translateY(0); } 50% { transform:scaleX(-1) translateY(-10px) rotate(6deg); } }
@keyframes fog  { from { transform:translateX(-6%); } to { transform:translateX(6%); } }
@keyframes bob  { 0%,100% { transform:translateY(0); } 50% { transform:translateY(8px); } }
@keyframes twinkle { 0%,100% { opacity:1; } 50% { opacity:.35; } }
@keyframes float { 0%,100% { transform:translateY(0) rotate(-2deg); } 50% { transform:translateY(-10px) rotate(2deg); } }

/* ---------- metric tiles: little treasure chests ---------- */
[data-testid="stMetric"] { position:relative; padding:14px 18px; border-radius:18px;
  background:linear-gradient(160deg, rgba(107,52,200,.7), rgba(42,16,96,.9));
  border:2px solid var(--gold); box-shadow:0 5px 0 rgba(0,0,0,.35), 0 0 20px rgba(177,92,240,.3);
  transition:transform .18s ease, box-shadow .18s ease; }
[data-testid="stMetric"]::after { content:"\\2693"; position:absolute; right:14px; top:8px; font-size:1.3rem;
  color:var(--gold); opacity:.55; }
[data-testid="stColumn"]:nth-child(2) [data-testid="stMetric"]::after { content:"\\1F5DD"; }
[data-testid="stColumn"]:nth-child(3) [data-testid="stMetric"]::after { content:"\\1F4DC"; }
[data-testid="stColumn"]:nth-child(4) [data-testid="stMetric"]::after { content:"\\1F48E"; }
[data-testid="stColumn"]:nth-child(2) [data-testid="stMetric"] { border-color:var(--teal); }
[data-testid="stColumn"]:nth-child(3) [data-testid="stMetric"] { border-color:var(--pink); }
[data-testid="stColumn"]:nth-child(4) [data-testid="stMetric"] { border-color:var(--orchid); }
[data-testid="stMetric"]:hover { transform:translateY(-4px); box-shadow:0 9px 0 rgba(0,0,0,.35), 0 0 30px rgba(240,107,196,.55); }
[data-testid="stMetricValue"], [data-testid="stMetricValue"] * { font-family:'Lilita One', sans-serif;
  font-weight:400; color:#fff !important; text-shadow:0 2px 0 var(--violet); }
[data-testid="stMetricLabel"], [data-testid="stMetricLabel"] * { color:var(--blush) !important; font-weight:600; }

/* ---------- buttons: glossy pills with a shimmer sweep ---------- */
.stButton > button, .stDownloadButton > button, [data-testid="stFormSubmitButton"] > button {
  position:relative; overflow:hidden; font-family:'Lilita One', sans-serif; font-weight:400;
  letter-spacing:.04em; font-size:1.02rem; color:#fff;
  background:linear-gradient(180deg, var(--orchid), var(--violet));
  border:2px solid var(--gold); border-radius:999px; padding:.5rem 1.4rem;
  box-shadow:0 5px 0 #2A1060, 0 8px 18px rgba(0,0,0,.35);
  transition:transform .15s ease, box-shadow .15s ease, filter .15s ease;
}
.stButton > button p, .stDownloadButton > button p, [data-testid="stFormSubmitButton"] > button p {
  color:inherit; font-family:inherit; }
.stButton > button::after, .stDownloadButton > button::after, [data-testid="stFormSubmitButton"] > button::after {
  content:""; position:absolute; top:0; bottom:0; left:-60%; width:40%; transform:skewX(-20deg);
  background:linear-gradient(100deg, transparent, rgba(255,255,255,.45), transparent); transition:left .55s ease; }
.stButton > button:hover, .stDownloadButton > button:hover, [data-testid="stFormSubmitButton"] > button:hover {
  color:#fff; border-color:var(--gold); filter:brightness(1.1); transform:translateY(-3px) scale(1.03);
  box-shadow:0 8px 0 #2A1060, 0 0 26px rgba(240,107,196,.7); }
.stButton > button:hover::after, .stDownloadButton > button:hover::after,
[data-testid="stFormSubmitButton"] > button:hover::after { left:130%; }
.stButton > button:active, .stDownloadButton > button:active, [data-testid="stFormSubmitButton"] > button:active {
  transform:translateY(4px); box-shadow:0 1px 0 #2A1060; }
.stButton > button[kind="primary"], button[data-testid="stBaseButton-primary"] {
  background:linear-gradient(180deg, #FFD770, var(--gold)); color:#2A1352;
  box-shadow:0 5px 0 var(--gold-d), 0 0 22px rgba(242,193,78,.5); animation:beacon 2.6s ease-in-out infinite; }
.stButton > button[kind="primary"]:hover, button[data-testid="stBaseButton-primary"]:hover {
  color:#2A1352; box-shadow:0 8px 0 var(--gold-d), 0 0 34px rgba(242,193,78,.9); }
button[data-testid="stBaseButton-primary"] p { color:#2A1352; }
.stDownloadButton > button { background:linear-gradient(180deg, #5BE6D6, var(--teal)); color:#0E2B33;
  box-shadow:0 5px 0 #1F8F85, 0 8px 18px rgba(0,0,0,.35); }
.stDownloadButton > button:hover { color:#0E2B33; box-shadow:0 8px 0 #1F8F85, 0 0 26px rgba(71,215,200,.7); }
@keyframes beacon { 50% { box-shadow:0 5px 0 var(--gold-d), 0 0 38px rgba(242,193,78,.9); } }
.stButton > button:focus-visible, .stDownloadButton > button:focus-visible { outline:3px solid var(--blush); outline-offset:3px; }

/* ---------- inputs ---------- */
[data-baseweb="input"], [data-baseweb="textarea"], [data-baseweb="select"] > div {
  background:rgba(18,6,43,.85) !important; border:2px solid var(--violet) !important; border-radius:12px !important;
  transition:box-shadow .15s, border-color .15s; }
[data-baseweb="input"] > div, [data-baseweb="base-input"] { background:transparent !important; border:0 !important; }
[data-baseweb="input"]:focus-within, [data-baseweb="textarea"]:focus-within, [data-baseweb="select"] > div:focus-within {
  border-color:var(--pink) !important; box-shadow:0 0 0 3px rgba(240,107,196,.35), 0 0 18px rgba(240,107,196,.5) !important; }
input, textarea { color:var(--parch) !important; }
[data-baseweb="tag"] { background:var(--gold) !important; border-radius:8px !important; }
[data-baseweb="tag"], [data-baseweb="tag"] * { color:#2A1352 !important; font-weight:600; }
[data-baseweb="popover"] > div { border:2px solid var(--gold); border-radius:12px;
  box-shadow:0 10px 30px rgba(0,0,0,.5); background:var(--deep); }
[data-baseweb="menu"] { background:var(--deep) !important; }
[role="option"]:hover, [role="option"][aria-selected="true"] { background:var(--plum) !important; }

/* ---------- tabs ---------- */
[data-baseweb="tab-list"] { gap:10px; background:transparent; }
[data-baseweb="tab-highlight"], [data-baseweb="tab-border"] { display:none !important; }
button[role="tab"] { font-family:'Lilita One', sans-serif; color:var(--blush); background:rgba(58,26,110,.6);
  border:2px solid rgba(242,193,78,.35); border-bottom:0; border-radius:14px 14px 0 0; padding:.5rem 1.4rem;
  transition:transform .15s, background .15s, border-color .15s; }
button[role="tab"] p { font-family:'Lilita One', sans-serif; font-size:1.05rem; color:inherit; }
button[role="tab"]:hover { background:var(--plum); border-color:var(--gold); transform:translateY(-3px); }
button[role="tab"][aria-selected="true"] { background:linear-gradient(180deg, var(--pink), var(--violet));
  color:#fff; border-color:var(--gold); box-shadow:0 0 22px rgba(240,107,196,.55); }

/* ---------- radio: pill stickers ---------- */
[data-testid="stRadio"] [role="radiogroup"] > label {
  background:rgba(58,26,110,.6); border:2px solid var(--violet); border-radius:999px; padding:.3rem 1rem;
  transition:transform .12s, background .12s, border-color .12s; }
[data-testid="stRadio"] [role="radiogroup"] > label:hover { transform:translateY(-2px); border-color:var(--pink); }
[data-testid="stRadio"] [role="radiogroup"] > label:has(input:checked) {
  background:linear-gradient(180deg, var(--pink), var(--violet)); border-color:var(--gold);
  box-shadow:0 0 16px rgba(240,107,196,.55); }

/* ---------- alerts ---------- */
[data-testid="stAlert"] { border:2px solid; border-radius:14px; color:var(--parch); animation:rise .4s ease both; }
[data-testid="stAlert"] * { color:var(--parch); }
[data-testid="stAlert"]:has([data-testid="stAlertContentSuccess"]) { background:rgba(71,215,200,.16); border-color:var(--teal); }
[data-testid="stAlert"]:has([data-testid="stAlertContentInfo"])    { background:rgba(177,92,240,.2);  border-color:var(--orchid); }
[data-testid="stAlert"]:has([data-testid="stAlertContentWarning"]) { background:rgba(242,193,78,.15); border-color:var(--gold); }
[data-testid="stAlert"]:has([data-testid="stAlertContentError"])   { background:rgba(240,107,196,.2); border-color:var(--pink); }
[data-testid="stToast"] { border:2px solid var(--gold) !important; border-radius:14px !important;
  background:var(--deep) !important; color:var(--parch) !important; box-shadow:0 0 24px rgba(240,107,196,.5) !important; }
[data-testid="stSpinner"] * { color:var(--blush) !important; }
@keyframes rise { from { opacity:0; transform:translateY(12px); } }

/* ---------- file drop zone ---------- */
[data-testid="stFileUploaderDropzone"] { background:rgba(107,52,200,.3); border:2px dashed var(--gold); border-radius:16px;
  transition:transform .18s, background .18s, box-shadow .18s; }
[data-testid="stFileUploaderDropzone"]:hover { background:rgba(240,107,196,.3); box-shadow:0 0 24px rgba(240,107,196,.5); transform:scale(1.01); }

/* ---------- tables ---------- */
[data-testid="stDataFrame"] { border:2px solid var(--gold); border-radius:12px; overflow:hidden;
  box-shadow:0 0 22px rgba(177,92,240,.35); }

/* ---------- sidebar ---------- */
section[data-testid="stSidebar"] { background:linear-gradient(180deg, #1D0B40, #3A1A6E 70%, #5B2A9E);
  border-right:3px solid var(--gold); }
section[data-testid="stSidebar"] [data-testid="stSidebarHeader"] { background:transparent; }
.mascot { text-align:center; margin:.2rem 0 1rem; }
.mascot img { width:170px; max-width:90%; height:auto; background:none; border:0; border-radius:0; box-shadow:none;
  filter:drop-shadow(0 8px 12px rgba(0,0,0,.5)) drop-shadow(0 0 14px rgba(240,107,196,.35));
  animation:float 4s ease-in-out infinite; }
.mascot p { margin:0; font-family:'Lilita One', sans-serif; color:var(--gold); letter-spacing:.04em; }

/* ---------- generating overlay: the captain pops up ---------- */
.gen-overlay { position:fixed; inset:0; z-index:1000000; display:grid; place-items:center;
  background:radial-gradient(circle at 50% 42%, rgba(240,107,196,.4), rgba(18,6,43,.94) 68%);
  animation:fade-in .25s ease both; }
.gen-card { position:relative; margin-top:5rem; text-align:center; padding:0 2.6rem 1.8rem;
  border:3px solid var(--gold); border-radius:28px;
  background:linear-gradient(180deg, rgba(58,26,110,.94), rgba(29,11,64,.96));
  box-shadow:0 0 0 8px rgba(107,52,200,.35), 0 0 70px rgba(240,107,196,.5);
  animation:pop-in .6s cubic-bezier(.2,1.5,.4,1) both; }
.gen-card .fig { width:190px; margin:-7.4rem auto 0; animation:float 1.8s ease-in-out infinite;
  filter:drop-shadow(0 12px 14px rgba(0,0,0,.5)); }
.gen-card .fig img, .treasure .fig img { width:100%; display:block; }
.gen-card .sp { position:absolute; color:var(--gold); font-size:1.4rem; animation:twinkle 1.4s ease-in-out infinite; }
.gen-title { margin-top:.3rem; font-family:'Lilita One', sans-serif; font-size:1.8rem; color:#fff;
  text-shadow:0 3px 0 var(--violet), 0 0 18px rgba(240,107,196,.8); }
.gen-msgs { position:relative; height:1.5rem; margin:.5rem 0 1rem; color:var(--blush); }
.gen-msgs span { position:absolute; left:0; right:0; opacity:0; animation:msg 7.2s infinite; }
.gen-msgs span:nth-child(2) { animation-delay:2.4s; } .gen-msgs span:nth-child(3) { animation-delay:4.8s; }
.gen-bar { width:240px; max-width:70vw; height:16px; margin:0 auto; border:2px solid var(--gold);
  border-radius:99px; overflow:hidden; background:rgba(18,6,43,.85); }
.gen-bar b { display:block; height:100%; width:0; border-radius:99px; background-size:28px 28px;
  background-image:repeating-linear-gradient(45deg, var(--pink) 0 10px, var(--orchid) 10px 20px);
  animation:fill 2.2s ease-out forwards, stripes .6s linear infinite; }
@keyframes fade-in { from { opacity:0; } }
@keyframes pop-in { 0% { opacity:0; transform:translateY(40px) scale(.5); } 100% { opacity:1; transform:none; } }
@keyframes msg { 0% { opacity:0; transform:translateY(6px); } 5%, 28% { opacity:1; transform:none; } 33%, 100% { opacity:0; } }
@keyframes fill { to { width:100%; } }
@keyframes stripes { to { background-position:28px 0; } }

/* ---------- success pop: pirate cheers, coins fly ---------- */
.treasure { position:fixed; right:24px; bottom:24px; z-index:1000000; display:flex; align-items:flex-end; gap:6px;
  pointer-events:none; animation:treasure 6s ease both; }
.treasure .fig { width:120px; animation:float 1.6s ease-in-out infinite; filter:drop-shadow(0 8px 10px rgba(0,0,0,.5)); }
.treasure .bubble { max-width:230px; margin-bottom:64px; padding:.7rem 1rem; border:2px solid var(--gold);
  border-radius:18px 18px 4px 18px; background:var(--parch); color:#2A1352;
  font-family:'Lilita One', sans-serif; font-size:1rem; line-height:1.25; box-shadow:4px 4px 0 var(--gold-d); }
.treasure .coins i { position:absolute; right:50px; bottom:110px; font-style:normal; font-size:1.3rem; opacity:0;
  animation:coin 1.8s ease-out var(--dl) both; }
@keyframes treasure { 0% { opacity:0; transform:translateY(60px) scale(.4); } 8% { opacity:1; transform:translateY(-14px) scale(1.08); }
  14% { transform:none; } 86% { opacity:1; transform:none; } 100% { opacity:0; transform:translateY(40px) scale(.9); visibility:hidden; } }
@keyframes coin { 0% { opacity:0; transform:translate(0,0); } 15% { opacity:1; transform:translate(calc(var(--x) * .5), -80px); }
  100% { opacity:0; transform:translate(var(--x), 70px) rotate(360deg); } }

@media (max-width:700px) {
  [data-testid="stMainBlockContainer"], .block-container { padding:1.2rem 1rem 2rem !important; }
  .hero .moon, .hero .kraken { display:none; } .hero .sail { width:110px; }
  .treasure .bubble { display:none; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation:none !important; transition:none !important; }
  .embers { display:none; }
  .hero .sail { left:auto; right:6%; }
  .gen-msgs span:first-child { opacity:1; } .gen-bar b { width:100%; }
  .treasure { animation:rm-fade 6s forwards !important; }
  @keyframes rm-fade { 0%, 85% { opacity:1; } 100% { opacity:0; visibility:hidden; } }
}
</style>
"""

