def _embers():
    r = random.Random(7)
    bits = "".join(
        f'<i style="left:{r.randint(2, 98)}%;--s:{r.uniform(3, 7):.1f}px;--d:{r.uniform(9, 20):.1f}s;'
        f'--delay:-{r.uniform(0, 18):.1f}s;--sway:{r.randint(-60, 60)}px"></i>'
        for _ in range(26))
    return f'<div class="mist-a"></div><div class="mist-b"></div><div class="embers" aria-hidden="true">{bits}</div>'


def inject_theme():
    st.markdown(_CSS, unsafe_allow_html=True)
    st.markdown(_embers(), unsafe_allow_html=True)


def hero():
    """Night-sea strip: ship sailing across, peeking octopus, a parrot flying past.
    Hover it and the sea gets rougher."""
    st.markdown(_HERO, unsafe_allow_html=True)


def mascot(name="NMIMS"):
    """School picture at the top of the sidebar."""
    st.markdown(_flat(f'<div class="mascot">{_SCHOOL}<p>{name}</p></div>'), unsafe_allow_html=True)


def gen_overlay():
    """Full-screen 'agents negotiating' scene. Render into an st.empty() and
    clear it when the work is done."""
    return _flat(f"""
<div class="gen-overlay" role="status" aria-live="polite">
<div class="gen-card">
<span class="sp" style="left:12%;top:-1rem">✦</span>
<span class="sp" style="right:12%;top:-2rem;animation-delay:.5s">✧</span>
<span class="sp" style="right:8%;top:3rem;animation-delay:.9s">✦</span>
<div class="fig">{_OWL}</div>
<div class="gen-title">Hoisting your timetable!</div>
<div class="gen-msgs"><span>Rooms are haggling over slots…</span><span>Departments are plotting their course…</span><span>Counting the doubloons…</span></div>
<div class="gen-bar"><b></b></div>
</div></div>
""")


def treasure_pop(clean=True):
    """Corner celebration: the owl cheers, a speech bubble, a burst of coins.
    Fades itself out after ~6 seconds."""
    msg = ("Treasure found! Zero clashes, a ship-shape timetable." if clean
           else "Land ho! Your timetable is ready.")
    coins = "".join(f'<i style="--x:{x}px;--dl:{d}s">🪙</i>'
                    for x, d in [(-90, .5), (-40, .7), (10, .6), (60, .9), (-120, 1.0), (30, 1.1)])
    return _flat(f"""
<div class="treasure" role="status"><div class="coins">{coins}</div>
<div class="bubble">{msg}</div><div class="fig">{_OWL}</div></div>
""")
